<?php declare(strict_types=1);require_once __DIR__.'/../../bootstrap/app.php';use App\Services\DriverService;use App\Security\Csrf;use App\Support\Url;$token=(string)($_GET['token']??$_POST['token']??'');$errors=[];$done=false;if($_SERVER['REQUEST_METHOD']==='POST'){if(!Csrf::verify($_POST['_csrf']??null))$errors[]='Invalid form token.';elseif(($_POST['password']??'')!==($_POST['password_confirmation']??''))$errors[]='Passwords do not match.';else try{DriverService::setupPassword($token,(string)$_POST['password']);$done=true;}catch(RuntimeException$e){$errors[]=$e->getMessage();}}?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Driver password setup · McCollins</title><link rel="stylesheet" href="<?=htmlspecialchars(Url::to('assets/css/app.css'),ENT_QUOTES,'UTF-8')?>"></head><body><main class="auth-page"><section class="auth-card"><h1>Driver password setup</h1><?php if($done):?><div class="success">Password created. McCollins Operations must still approve and activate the Driver role.</div><a class="button" href="<?=htmlspecialchars(Url::to('auth/login.php'),ENT_QUOTES,'UTF-8')?>">Go to login</a><?php else:foreach($errors as$e):?><div class="error"><?=htmlspecialchars($e,ENT_QUOTES,'UTF-8')?></div><?php endforeach;?><form method="post"><input type="hidden" name="_csrf" value="<?=htmlspecialchars(Csrf::token(),ENT_QUOTES,'UTF-8')?>"><input type="hidden" name="token" value="<?=htmlspecialchars($token,ENT_QUOTES,'UTF-8')?>"><div class="field"><label>Password (12+ characters)</label><input type="password" name="password" minlength="12" required></div><div class="field"><label>Confirm password</label><input type="password" name="password_confirmation" minlength="12" required></div><button class="button">Create password</button></form><?php endif;?></section></main></body></html>
